(13, 'sms', 'appointment_reminder', 0, 'Recordatorio vespertino al cliente sobre cita del día siguiente (requiere configuración cron)', '', 'Estimado/a {client_name}.\nNos gustaría recordarle que tiene una reserva de {service_name} mañana a las {appointment_time}. Le esperamos en {company_address}.\nGracias por escoger nuestra compañia.\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":1,\"perform\":\"before\",\"at_hour\":18,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":-24}'),
(14, 'voice', 'appointment_reminder', 0, 'Recordatorio vespertino al cliente sobre cita del día siguiente (requiere configuración cron)', '', 'Estimado/a {client_name}.\nNos gustaría recordarle que tiene una reserva de {service_name} mañana a las {appointment_time}. Le esperamos en {company_address}.\nGracias por escoger nuestra compañia.\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":1,\"perform\":\"before\",\"at_hour\":18,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":-24}'),
(15, 'sms', 'appointment_reminder', 0, 'Seguimiento de mensaje al día siguiente de la cita (requiere configuración cron)', '', 'Estimado/a {client_name}.\nGracias por escoger {company_name}. Esperamos que esté satisfecho con su {service_name}.\nGracias y esperamos volver a verle pronto.\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":21,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(16, 'sms', 'staff_day_agenda', 0, 'Notificación vespertina al Personal con la agenda del día siguiente (requiere configuración cron)', '', 'Hola.\nSu agenda para mañana es:\n{next_day_agenda}', 1, 0, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":18,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":-24}'),
