(21, 'email', 'customer_new_wp_user', 1, 'Notificación a los clientes acerca de sus datos de acceso de usuario de WordPress', 'Nuevo cliente', 'Hola. \nUna cuenta fue creado por usted en {site_address}\n\nSus datos de usuario:\nusuario: {new_username}\ncontraseña: {new_password}\n\nGracias.', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(22, 'email', 'staff_new_wp_user', 1, 'Detalles de inicio de sesión de usuario de WordPress del nuevo miembro del personal', 'Nuevo miembro del personal', 'Hola. \nUna cuenta fue creado por usted en {site_address}\n\nSus datos de usuario:\nusuario: {new_username}\ncontraseña: {new_password}\n\nGracias.', 1, 0, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(23, 'email', 'appointment_reminder', 0, 'Recordatorio vespertino al cliente sobre cita del día siguiente (requiere configuración cron)', 'Su cita en {company_name}', 'Apreciado(a) {client_name}.\n\nQueremos recordarte que tienes una cita para {service_name} mañana a las {appointment_time}. Te esperaremos en {company_address}.\n\nGracias por confiar en nosotros.\n\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":1,\"perform\":\"before\",\"at_hour\":18,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":-24}'),
(24, 'email', 'appointment_reminder', 0, 'Seguimiento de mensaje al día siguiente de la cita (requiere configuración cron)', 'Su visita a {company_name}', 'Apreciado(a) {client_name}.\n\nGracias por elegir {company_name}. Esperamos hayas quedado satisfecho(a) con tu {service_name}.\n\nQueremos verte nuevamente por aquí.\n\n¡Qué tengas un feliz día!.\n\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":21,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(25, 'email', 'customer_birthday', 0, 'Saludo del cumpleaños de los clientes (requiere configuración de cron)', 'Feliz cumpleaños.', 'Estimado {client_name},\n\n¡Feliz cumpleaños!\nLe deseamos todo lo mejor.\nQue usted y su familia sean felices y saludables.\n\nGracias por escoger nuestra compañia.\n\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(26, 'email', 'staff_day_agenda', 0, 'Notificación vespertina al Personal con la agenda del día siguiente (requiere configuración cron)', 'Su agenda para {tomorrow_date}', 'Hola.\n\nTu agenda para mañana:\n\n{next_day_agenda}', 1, 0, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":3,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(27, 'email', 'new_booking_combined', 0, 'Notificación de nueva reserva combinada', 'Información de tu cita', 'Estimado {client_name}.\n\nEsta es una confirmación de haber conseguido los siguientes elementos:\n\n{cart_info}\n\nGracias por elegir nuestra empresa.\n\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(28, 'email', 'new_gift_card', 1, 'Notificación al cliente sobre la tarjeta de regalo comprada', 'Su tarjeta regalo en {company_name}', 'Estimado/a {client_name},\n\nEsto es una confirmación de que la siguiente Tarjeta de regalo {gift_card} ha sido comprada en {company_name}.\n\nLe esperamos en {company_address}.\n\n\n\nGracias por escoger nuestra compañia.\n\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(29, 'sms', 'customer_new_wp_user', 1, 'Notificación a los clientes acerca de sus datos de acceso de usuario de WordPress', '', 'Hola.\nUna cuenta fue creado por usted en {site_address}\nSus datos de usuario:\nusuario: {new_username}\ncontraseña: {new_password}\n\nGracias.', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(30, 'sms', 'staff_new_wp_user', 1, 'Detalles de inicio de sesión de usuario de WordPress del nuevo miembro del personal', '', 'Hola.\nUna cuenta fue creado por usted en {site_address}\nSus datos de usuario:\nusuario: {new_username}\ncontraseña: {new_password}\n\nGracias.', 1, 0, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),
(31, 'sms', 'customer_birthday', 0, 'Saludo del cumpleaños de los clientes (requiere configuración de cron)', '', 'Estimado {client_name},\n¡Feliz cumpleaños!\nLe deseamos todo lo mejor.\nQue usted y su familia sean felices y saludables.\nGracias por escoger nuestra compañia.\n{company_name}\n{company_phone}\n{company_website}', 0, 1, 0, 0, NULL, 0, 0, 0, '{\"status\":\"any\",\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0,\"existing_event_with_date\":{\"at_hour\":9}}'),
