INSERT INTO `ebMMaZG04_bookly_shop` (`id`, `plugin_id`, `highlighted`, `priority`, `demo_url`, `title`, `slug`, `description`, `url`, `icon`, `image`, `price`, `sub_price`, `sales`, `rating`, `reviews`, `published`, `seen`, `visible`, `license`, `content`, `bundle_plugins`, `created_at`) VALUES
(1, 7226091, 1, 100, 'https://www.booking-wp-plugin.com/demo/1/', 'Bookly Pro', 'bookly-addon-pro', 'Bring appointment scheduling process to the next level with Bookly Pro (Add-on). Pro version turns Bookly plugin into the professional appointment management system. Unlock Advanced Customer management, Service provider management, Services management, Email and SMS notifications, Booking management capabilities. Connect payment gateways and modify Pro version with other add-ons available only with Bookly Pro and more.', 'https://www.booking-wp-plugin.com/pricing/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-pro.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-pro.jpg', 129.00, '$49.00', 56404, 4.53, 1174, '2014-04-12 17:14:52', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bring appointment scheduling process to the next level with Bookly Pro (Add-on). Pro version turns Bookly plugin into the professional appointment management system. Unlock Advanced Customer management, Service provider management, Services management, Email and SMS notifications, Booking management capabilities. Connect payment gateways and modify Pro version with other add-ons available only with Bookly Pro and more.\",\"badge\":\"Core\",\"short\":\"The essentials for running your bookings with ease.\",\"inherit\":\"Everything you need for professional booking\",\"features\":[{\"body\":\"Every customer in one list, with their booking history, contact details and notes.\",\"title\":\"Customer management\"},{\"body\":\"Staff with their own working hours, services and days off \\u2014 each booking goes to the right person.\",\"title\":\"Staff & service providers\"},{\"body\":\"Services grouped into categories, each with its own duration, price and capacity.\",\"title\":\"Services & categories\"},{\"body\":\"Confirmations, reminders and follow-ups sent automatically, on templates you write yourself.\",\"title\":\"Email & SMS notifications\"}],\"footnote\":\"The foundation for Bookly add-ons\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":129,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":49,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]}}}', NULL, '2026-09-23 06:48:22'),
(2, 13903524, 0, 0, '', 'Multisite', 'bookly-addon-multisite', 'Bookly Multisite (Add-on) enables you to use a single instance of the Bookly plugin across your entire Multisite network. This means that each site within your network will have its own unique list of services, staff members, appointments, and settings. It’s an efficient and convenient way to manage your bookings across multiple sites from a single point of access.', 'https://www.booking-wp-plugin.com/add-ons/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-multisite.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-multisite.jpg', 49.00, '$15.95', 737, 5.00, 9, '2015-12-04 16:38:03', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Multisite (Add-on) enables you to use a single instance of the Bookly plugin across your entire Multisite network. This means that each site within your network will have its own unique list of services, staff members, appointments, and settings. It\\u2019s an efficient and convenient way to manage your bookings across multiple sites from a single point of access.\",\"tags\":[\"Staff & Teams\",\"Automation\"],\"short\":\"Run Bookly across a WordPress network.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":49,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":15.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(3, 15552320, 0, 0, 'https://www.booking-wp-plugin.com/demo/extras/', 'Service Extras', 'bookly-addon-service-extras', 'Bookly Service Extras (Add-on) allows you to offer extra items, services, products, equipment, or options that customers can book along with the regular appointment created via Bookly. These additional items can affect the overall price and duration of the appointment as selected by the client.', 'https://www.booking-wp-plugin.com/add-ons/add-extras-services/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-service-extras.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-service-extras.jpg', 49.00, '$15.95', 4141, 4.49, 37, '2016-04-01 15:29:11', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Service Extras (Add-on) allows you to offer extra items, services, products, equipment, or options that customers can book along with the regular appointment created via Bookly. These additional items can affect the overall price and duration of the appointment as selected by the client.\",\"tags\":[\"Booking form\",\"Payments\"],\"short\":\"Paid add-ons customers pick alongside a service.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":49,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":15.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(4, 17328208, 0, 0, 'https://www.booking-wp-plugin.com/demo/locations/', 'Locations', 'bookly-addon-locations', 'Does your company operate in more than one place? Bookly Locations (Add-on) makes it possible to associate staff members and services with different locations, so your clients can pick where they prefer to receive services before they schedule a date and time for their visit.\r\n', 'https://www.booking-wp-plugin.com/add-ons/add-service-locations/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-locations.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-locations.jpg', 39.00, '$12.95', 3612, 4.46, 35, '2016-08-03 17:49:31', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Does your company operate in more than one place? Bookly Locations (Add-on) makes it possible to associate staff members and services with different locations, so your clients can pick where they prefer to receive services before they schedule a date and time for their visit.\",\"tags\":[\"Staff & Teams\",\"Booking form\"],\"short\":\"Multiple venues with their own staff and hours.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(5, 17367838, 0, 0, 'https://www.booking-wp-plugin.com/demo/chain/', 'Chain Appointments', 'bookly-addon-chain-appointments', 'Let your clients book several consecutive appointments in one visit. With the Bookly Chain Appointments (Add-on), your clients can choose multiple services from different staff members at the first step of the booking process. Bookly will find available time slots when all services can be delivered sequentially during a single visit.', 'https://www.booking-wp-plugin.com/add-ons/chain-bookings/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-chain-appointments.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-chain-appointments.jpg', 29.00, '$9.95', 1604, 4.80, 5, '2016-08-09 17:40:29', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Let your clients book several consecutive appointments in one visit. With the Bookly Chain Appointments (Add-on), your clients can choose multiple services from different staff members at the first step of the booking process. Bookly will find available time slots when all services can be delivered sequentially during a single visit.\",\"tags\":[\"Calendar & Sync\",\"Booking form\"],\"short\":\"Sequences of linked visits booked together.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(6, 17457141, 0, 0, 'https://www.booking-wp-plugin.com/demo/multiply/', 'Multiply Appointments', 'bookly-addon-multiply-appointments', 'Let your clients determine the length of their visit by booking back to back sessions of the same service. Bookly Multiply Appointments (Add-on) makes it possible for your clients to select a number of appointments they would like to get in a row with the same service provider. Bookly will automatically calculate the price of such reservation and offer time slots that can accommodate the stated number of identical appointments.', 'https://www.booking-wp-plugin.com/add-ons/multiply-appointments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-multiply-appointments.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-multiply-appointments.jpg', 29.00, '$9.95', 1065, 4.00, 3, '2016-08-16 16:02:12', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Let your clients determine the length of their visit by booking back to back sessions of the same service. Bookly Multiply Appointments (Add-on) makes it possible for your clients to select a number of appointments they would like to get in a row with the same service provider. Bookly will automatically calculate the price of such reservation and offer time slots that can accommodate the stated number of identical appointments.\",\"tags\":[\"Calendar & Sync\",\"Booking form\"],\"short\":\"Repeat the same booking across several slots.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(7, 17956131, 0, 0, 'https://www.booking-wp-plugin.com/demo/deposit/', 'Deposit Payments', 'bookly-addon-deposit-payments', 'Do you want to minimize the number of missed appointments and reduce cancellations? With the Bookly Deposit Payments (Add-on), you can require clients to pay a deposit at the time of booking to secure their appointment. By collecting a portion of the service cost in advance, you can minimize the risk of no-shows and ensure that the client is committed to their appointment. The remaining amount can then be paid offline when the client arrives for their appointment.', 'https://www.booking-wp-plugin.com/add-ons/accept-deposit-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-deposit-payments.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-deposit-payments.jpg', 39.00, '$12.95', 2184, 3.75, 12, '2016-09-22 18:11:00', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you want to minimize the number of missed appointments and reduce cancellations? With the Bookly Deposit Payments (Add-on), you can require clients to pay a deposit at the time of booking to secure their appointment. By collecting a portion of the service cost in advance, you can minimize the risk of no-shows and ensure that the client is committed to their appointment. The remaining amount can then be paid offline when the client arrives for their appointment.\",\"tags\":[\"Payments\",\"Booking form\"],\"short\":\"Let customers pay part of the price upfront.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(8, 18611122, 0, 0, 'https://www.booking-wp-plugin.com/demo/special-days/', 'Special Days', 'bookly-addon-special-days', 'Bookly Special Days (Add-on) enables you to change the default working hours of your staff on specific days of the year. This means you can create customized work schedules that differ from the regular ones, such as shorter or longer workdays, including breaks. These special days’ working hours will be taken into account when Bookly checks the service provider’s availability, providing your clients with accurate booking times.', 'https://www.booking-wp-plugin.com/add-ons/add-special-days-staffs-schedules/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-special-days.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-special-days.jpg', 39.00, '$12.95', 3604, 4.53, 19, '2016-11-07 01:25:43', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Special Days (Add-on) enables you to change the default working hours of your staff on specific days of the year. This means you can create customized work schedules that differ from the regular ones, such as shorter or longer workdays, including breaks. These special days\\u2019 working hours will be taken into account when Bookly checks the service provider\\u2019s availability, providing your clients with accurate booking times.\",\"tags\":[\"Calendar & Sync\",\"Staff & Teams\"],\"short\":\"Holidays and exceptions across the calendar.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(9, 18704535, 0, 0, 'https://www.booking-wp-plugin.com/demo/special-hours/', 'Special Hours', 'bookly-addon-special-hours', 'Do you want to offer flexible pricing options for your services? With the Bookly Special Hours (Add-on), you can easily set up dynamic pricing based on the time of day or day of the week. You can offer discounted rates for morning appointments or increase prices for evening or weekend bookings. This allows you to tailor your pricing to the needs of your business and customers.', 'https://www.booking-wp-plugin.com/add-ons/set-flexible-prices/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-special-hours.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-special-hours.jpg', 29.00, '$9.95', 872, 4.33, 6, '2016-11-09 01:22:54', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you want to offer flexible pricing options for your services? With the Bookly Special Hours (Add-on), you can easily set up dynamic pricing based on the time of day or day of the week. You can offer discounted rates for morning appointments or increase prices for evening or weekend bookings. This allows you to tailor your pricing to the needs of your business and customers.\",\"tags\":[\"Calendar & Sync\",\"Staff & Teams\",\"Payments\"],\"short\":\"Per-service pricing and hours for each provider.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(10, 18874038, 0, 0, 'https://www.booking-wp-plugin.com/demo/srv-schedule/', 'Service Schedule', 'bookly-addon-service-schedule', 'Do you offer unique types of services that are only available during specific times or days? With the Bookly Service Schedule (Add-on), you can easily limit the availability of your services to specific hours or days. This allows staff members to follow their regular schedules but booking times for a specific service only appear in the Bookly form when they overlap with the staff’s working hours.', 'https://www.booking-wp-plugin.com/add-ons/limit-service-availability/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-service-schedule.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-service-schedule.jpg', 29.00, '$9.95', 3860, 4.28, 18, '2016-11-22 05:03:19', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you offer unique types of services that are only available during specific times or days? With the Bookly Service Schedule (Add-on), you can easily limit the availability of your services to specific hours or days. This allows staff members to follow their regular schedules but booking times for a specific service only appear in the Bookly form when they overlap with the staff\\u2019s working hours.\",\"tags\":[\"Calendar & Sync\",\"Staff & Teams\"],\"short\":\"Hours that differ per service, not per staff.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(11, 19497634, 0, 0, 'https://www.booking-wp-plugin.com/demo/recurring/', 'Recurring Appointments', 'bookly-addon-recurring-appointments', 'Do you want to streamline your clients’ booking experience and encourage them to schedule regular visits? With the Bookly Recurring Appointments (Add-on), you can easily allow clients to schedule appointments weeks or months in advance. This feature allows you to automate the process of creating a series of appointments at a custom repeat interval, making it simple for clients to schedule regular appointments with just a few clicks in the Bookly booking form.', 'https://www.booking-wp-plugin.com/add-ons/recurring-appointments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-recurring-appointments.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-recurring-appointments.jpg', 39.00, '$12.95', 2209, 3.86, 14, '2017-02-23 17:42:00', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you want to streamline your clients\\u2019 booking experience and encourage them to schedule regular visits? With the Bookly Recurring Appointments (Add-on), you can easily allow clients to schedule appointments weeks or months in advance. This feature allows you to automate the process of creating a series of appointments at a custom repeat interval, making it simple for clients to schedule regular appointments with just a few clicks in the Bookly booking form.\",\"tags\":[\"Calendar & Sync\",\"Booking form\",\"Automation\"],\"short\":\"Weekly and monthly repeats in one booking.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(12, 19617518, 0, 0, '', 'PayPal Payments Standard', 'bookly-addon-paypal-payments-standard', 'If you’re looking for a hassle-free way to process online payments during the booking process, Bookly PayPal Payments Standard (Add-on) is the perfect solution for you. By integrating this add-on with your Bookly PRO booking form, you can offer your customers a secure and popular payment gateway to pay via credit card or PayPal account. With all payments processed through PayPal, you can rest assured that the transaction is safe and reliable.', 'https://www.booking-wp-plugin.com/add-ons/paypal-standard-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-paypal-payments-standard.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-paypal-payments-standard.jpg', 29.00, '$9.95', 2002, 4.50, 8, '2017-03-22 04:29:25', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"If you\\u2019re looking for a hassle-free way to process online payments during the booking process, Bookly PayPal Payments Standard (Add-on) is the perfect solution for you. By integrating this add-on with your Bookly PRO booking form, you can offer your customers a secure and popular payment gateway to pay via credit card or PayPal account. With all payments processed through PayPal, you can rest assured that the transaction is safe and reliable.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"The classic PayPal redirect checkout.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(13, 20005540, 0, 0, 'https://www.booking-wp-plugin.com/demo/staff-cabinet/', 'Staff Cabinet', 'bookly-addon-staff-cabinet', 'With the Bookly Staff Cabinet (Add-on), you can set up and provide each employee with their own personal account to manage their calendars, details, schedules, and other settings directly on the front end of your site. This eliminates the need for staff members to access the WordPress admin panel. By allowing employees to log in to their own Staff Cabinet, you can streamline the appointment management process and improve efficiency.', 'https://www.booking-wp-plugin.com/add-ons/personal-staff-cabinet-employees/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-staff-cabinet.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-staff-cabinet.jpg', 39.00, '$12.95', 2725, 4.15, 20, '2017-05-26 16:11:36', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"With the Bookly Staff Cabinet (Add-on), you can set up and provide each employee with their own personal account to manage their calendars, details, schedules, and other settings directly on the front end of your site. This eliminates the need for staff members to access the WordPress admin panel. By allowing employees to log in to their own Staff Cabinet, you can streamline the appointment management process and improve efficiency.\",\"tags\":[\"Staff & Teams\",\"Automation\"],\"short\":\"A front-end panel for staff to run their day.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(14, 20685954, 0, 0, '', 'PayU Latam', 'bookly-addon-payu-latam', 'Looking for a seamless and convenient way to accept online payments during booking on your website? Bookly PayU Latam (Add-on) enables integration of PayU Latam payment solution, which is a widely used payment platform in Latin America, into your Bookly PRO booking form. Your customers can easily pay online for your services using the PayU Checkout for secure transaction processing.', 'https://www.booking-wp-plugin.com/add-ons/payu-latam-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-payu-latam.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-payu-latam.jpg', 29.00, '$9.95', 117, 0.00, 2, '2017-10-04 22:22:08', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Looking for a seamless and convenient way to accept online payments during booking on your website? Bookly PayU Latam (Add-on) enables integration of PayU Latam payment solution, which is a widely used payment platform in Latin America, into your Bookly PRO booking form. Your customers can easily pay online for your services using the PayU Checkout for secure transaction processing.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Local card payments across Latin America.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(15, 20917406, 0, 0, 'https://www.booking-wp-plugin.com/demo/waiting-list/', 'Waiting List', 'bookly-addon-waiting-list', 'Do you want to provide clients with the option to join a waiting list for fully-booked time slots? The Bookly Waiting List (Add-on) allows you to enable this feature in your Bookly booking system. If a cancellation occurs, you can quickly fill the open time slot by notifying the clients on the waiting list. Bookly will automatically notify the service provider about the available time slot, along with a list of customers in line. ', 'https://www.booking-wp-plugin.com/add-ons/add-customers-waiting-list/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-waiting-list.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-waiting-list.jpg', 29.00, '$9.95', 632, 3.67, 3, '2017-11-09 17:58:26', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you want to provide clients with the option to join a waiting list for fully-booked time slots? The Bookly Waiting List (Add-on) allows you to enable this feature in your Bookly booking system. If a cancellation occurs, you can quickly fill the open time slot by notifying the clients on the waiting list. Bookly will automatically notify the service provider about the available time slot, along with a list of customers in line.\",\"tags\":[\"Customers\",\"Automation\"],\"short\":\"Notify customers the moment a slot frees up.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(16, 20952783, 0, 0, 'https://www.booking-wp-plugin.com/demo/packages/', 'Packages', 'bookly-addon-packages', 'Do your clients book the same service regularly? Why not offer them a package? With the Bookly Packages (Add-on), you can create deals for a particular service, allowing clients to book their favorite treatment in one package. Offering package deals can help to increase customer loyalty and encourage more sales. You can also set discounts on packages and set a validity period to ensure that customers use their package deals.', 'https://www.booking-wp-plugin.com/add-ons/offer-package-deals/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-packages.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-packages.jpg', 29.00, '$9.95', 954, 2.71, 7, '2017-11-14 18:45:26', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do your clients book the same service regularly? Why not offer them a package? With the Bookly Packages (Add-on), you can create deals for a particular service, allowing clients to book their favorite treatment in one package. Offering package deals can help to increase customer loyalty and encourage more sales. You can also set discounts on packages and set a validity period to ensure that customers use their package deals.\",\"tags\":[\"Payments\",\"Customers\",\"Marketing\"],\"short\":\"Sell prepaid sets of appointments as one product.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(17, 21113698, 0, 0, '', '2Checkout', 'bookly-addon-2checkout', 'Looking for a safe and convenient way to accept online payments via your Bookly booking form? Bookly 2Checkout (Add-on) allows you to integrate the 2сheckout payment solution – a leading global payment solution that enables companies to accept credit card payments from buyers around the world – into your Bookly PRO booking form. With this payment gateway, you can offer your clients a hassle-free payment experience that’s both secure and reliable.', 'https://www.booking-wp-plugin.com/add-ons/2checkout/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-2checkout.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-2checkout.jpg', 29.00, '$9.95', 47, 0.00, 0, '2017-12-12 10:30:34', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Looking for a safe and convenient way to accept online payments via your Bookly booking form? Bookly 2Checkout (Add-on) allows you to integrate the 2\\u0441heckout payment solution \\u2013 a leading global payment solution that enables companies to accept credit card payments from buyers around the world \\u2013 into your Bookly PRO booking form. With this payment gateway, you can offer your clients a hassle-free payment experience that\\u2019s both secure and reliable.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Global checkout through the 2Checkout gateway.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(18, 21113750, 0, 0, '', 'Authorize.Net', 'bookly-addon-authorize-net', 'Simplify the payment process for your customers by integrating a reliable and easy payment method into your website. With the Bookly Authorize.Net (Add-on), you can seamlessly integrate the Authorize.net payment solution into your Bookly PRO booking form. Your clients can pay for their appointments instantly with credit card via one of the most popular payment gateways.', 'https://www.booking-wp-plugin.com/add-ons/authorize-net-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-authorize-net.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-authorize-net.jpg', 29.00, '$9.95', 251, 0.00, 0, '2017-12-12 10:30:24', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Simplify the payment process for your customers by integrating a reliable and easy payment method into your website. With the Bookly Authorize.Net (Add-on), you can seamlessly integrate the Authorize.net payment solution into your Bookly PRO booking form. Your clients can pay for their appointments instantly with credit card via one of the most popular payment gateways.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Accept cards through your Authorize.Net account.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(19, 21113860, 0, 0, 'https://www.booking-wp-plugin.com/demo/coupons/', 'Coupons', 'bookly-addon-coupons', 'Would you like to improve customer loyalty, increase your sales, or attract new clients? With the Bookly Coupons (Add-on), you can create and manage promotional codes that customers can apply during checkout in the Bookly booking form. Once a coupon is used, the service price will automatically be reduced, and you’ll receive a record of the discount in the Bookly payment reports.', 'https://www.booking-wp-plugin.com/add-ons/use-coupons-promote-service/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-coupons.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-coupons.jpg', 39.00, '$12.95', 2672, 4.33, 6, '2017-12-12 10:39:37', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Would you like to improve customer loyalty, increase your sales, or attract new clients? With the Bookly Coupons (Add-on), you can create and manage promotional codes that customers can apply during checkout in the Bookly booking form. Once a coupon is used, the service price will automatically be reduced, and you\\u2019ll receive a record of the discount in the Bookly payment reports.\",\"tags\":[\"Marketing\",\"Payments\"],\"short\":\"Discount codes with usage limits and expiry.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(20, 21113970, 0, 0, 'https://www.booking-wp-plugin.com/demo/custom-fields/', 'Custom Fields', 'bookly-addon-custom-fields', 'With the Bookly Custom Fields (Add-on), you can add extra fields of different types to the Details step of the Bookly booking form. This feature allows you to gather more specific information from your clients before they complete their booking. The custom fields will be added to the appointment details in the Bookly Calendar, and can be updated if necessary.', 'https://www.booking-wp-plugin.com/add-ons/various-types-custom-fields-booking-form/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-custom-fields.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-custom-fields.jpg', 59.00, '$18.95', 6962, 4.60, 25, '2017-12-12 10:40:39', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"With the Bookly Custom Fields (Add-on), you can add extra fields of different types to the Details step of the Bookly booking form. This feature allows you to gather more specific information from your clients before they complete their booking. The custom fields will be added to the appointment details in the Bookly Calendar, and can be updated if necessary.\",\"tags\":[\"Booking form\",\"Customers\"],\"short\":\"Ask anything you need on the booking form.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":59,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":18.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(21, 21114042, 0, 0, '', 'Mollie', 'bookly-addon-mollie', 'Need a secure and easy method of accepting online payments through your Bookly booking form? The Bookly Mollie (Add-on) offers seamless integration with Mollie, one of the leading payment platforms in Europe. Mollie enables companies to accept credit card payments from buyers, providing a convenient and trustworthy payment experience. By integrating Mollie with Bookly PRO, you can offer your customers a reliable method of paying for their bookings directly on your website.', 'https://www.booking-wp-plugin.com/add-ons/mollie-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-mollie.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-mollie.jpg', 39.00, '$12.95', 1024, 3.67, 3, '2017-12-12 10:43:25', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Need a secure and easy method of accepting online payments through your Bookly booking form? The Bookly Mollie (Add-on) offers seamless integration with Mollie, one of the leading payment platforms in Europe. Mollie enables companies to accept credit card payments from buyers, providing a convenient and trustworthy payment experience. By integrating Mollie with Bookly PRO, you can offer your customers a reliable method of paying for their bookings directly on your website.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"European payment methods in one gateway.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(22, 21114096, 0, 0, '', 'Payson', 'bookly-addon-payson', 'Bookly Payson (Add-on) allows you to seamlessly integrate the Payson payment solution into your Bookly PRO booking form, providing customers with a convenient and secure payment experience. Payson Checkout is designed to increase the number of completed transactions and supports payment via online bank account or credit card. By integrating Payson with Bookly PRO, you can offer clients a reliable method of paying for their bookings directly on your website.', 'https://www.booking-wp-plugin.com/add-ons/payson/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-payson.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-payson.jpg', 29.00, '$9.95', 17, 0.00, 1, '2017-12-12 10:44:08', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Payson (Add-on) allows you to seamlessly integrate the Payson payment solution into your Bookly PRO booking form, providing customers with a convenient and secure payment experience. Payson Checkout is designed to increase the number of completed transactions and supports payment via online bank account or credit card. By integrating Payson with Bookly PRO, you can offer clients a reliable method of paying for their bookings directly on your website.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Nordic payments through Payson.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(23, 21114146, 0, 0, '', 'Stripe', 'bookly-addon-stripe', 'Bookly Stripe (Add-on) enables your customers to easily and securely pay for their appointments without being redirected away from the Bookly booking form. By integrating the Stripe payment solution into your Bookly PRO booking form, you can streamline the payment process for your customers, making it quick and convenient to complete transactions.', 'https://www.booking-wp-plugin.com/add-ons/stripe-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-stripe.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-stripe.jpg', 39.00, '$12.95', 4499, 4.50, 16, '2017-12-12 10:46:42', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Stripe (Add-on) enables your customers to easily and securely pay for their appointments without being redirected away from the Bookly booking form. By integrating the Stripe payment solution into your Bookly PRO booking form, you can streamline the payment process for your customers, making it quick and convenient to complete transactions.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Card payments through Stripe at booking time.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(24, 21344225, 0, 0, 'https://www.booking-wp-plugin.com/demo/group-booking/', 'Group Booking', 'bookly-addon-group-booking', 'Bookly Group Booking (Add-on) allows clients to book appointments for multiple people at the same time. The add-on enables you to set the minimum and maximum capacity of the service and accept group bookings for the same appointment slot. In the Bookly booking form, clients can specify the number of people they are booking for, and Bookly ensures that the service provider can accommodate the group.', 'https://www.booking-wp-plugin.com/add-ons/accept-group-bookings/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-group-booking.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-group-booking.jpg', 39.00, '$12.95', 5371, 4.28, 18, '2018-02-01 01:33:45', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Group Booking (Add-on) allows clients to book appointments for multiple people at the same time. The add-on enables you to set the minimum and maximum capacity of the service and accept group bookings for the same appointment slot. In the Bookly booking form, clients can specify the number of people they are booking for, and Bookly ensures that the service provider can accommodate the group.\",\"tags\":[\"Booking form\",\"Customers\"],\"short\":\"Several attendees on a single time slot.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(25, 21344290, 0, 0, 'https://www.booking-wp-plugin.com/demo/customer-groups/', 'Customer Groups', 'bookly-addon-customer-groups', 'The Bookly Customer Groups (Add-on) allows you to easily create and manage customer groups in Bookly, giving you the ability to set specific rules for each group. By categorizing your clients, you can control how their bookings are processed, set customized pricing for their appointments, and determine which services are visible to them in the Bookly booking form.', 'https://www.booking-wp-plugin.com/add-ons/organize-clients-groups/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-customer-groups.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-customer-groups.jpg', 29.00, '$9.95', 620, 0.00, 1, '2018-02-01 02:03:48', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"The Bookly Customer Groups (Add-on) allows you to easily create and manage customer groups in Bookly, giving you the ability to set specific rules for each group. By categorizing your clients, you can control how their bookings are processed, set customized pricing for their appointments, and determine which services are visible to them in the Bookly booking form.\",\"tags\":[\"Customers\",\"Marketing\"],\"short\":\"Group-level discounts and visibility rules.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(26, 21344354, 0, 0, 'https://www.booking-wp-plugin.com/demo/files/', 'Files', 'bookly-addon-files', 'File uploading feature simplifies the process of collecting information required for appointments. Bookly Files (Add-on) makes it possible for the clients to attach files related to their visit directly in the Bookly online booking form. All uploaded files will be available for review and update in the booking details. Important: Bookly Files (Add-on) requires Bookly Custom Fields (Add-on) installed and activated.', 'https://www.booking-wp-plugin.com/add-ons/attach-files-booking-form/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-files.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-files.jpg', 29.00, '$9.95', 946, 3.00, 9, '2018-02-01 02:07:58', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"File uploading feature simplifies the process of collecting information required for appointments. Bookly Files (Add-on) makes it possible for the clients to attach files related to their visit directly in the Bookly online booking form. All uploaded files will be available for review and update in the booking details. Important: Bookly Files (Add-on) requires Bookly Custom Fields (Add-on) installed and activated.\",\"tags\":[\"Booking form\",\"Customers\"],\"short\":\"Collect attachments with each appointment.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(27, 21574371, 0, 0, 'https://www.booking-wp-plugin.com/demo/compound-services/', 'Compound Services', 'bookly-addon-compound-services', 'With the Bookly Compound Services (Add-on), you can combine existing services with spare time to create a separate complex service that clients can book a complete appointment with multiple services as any regular appointment. Each service included in the compound appointment will be performed by a relevant staff member who will only be reserved for their part of the service.', 'https://www.booking-wp-plugin.com/add-ons/group-services-complex-appointments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-compound-services.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-compound-services.jpg', 29.00, '$9.95', 359, 0.00, 2, '2018-03-13 06:08:47', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"With the Bookly Compound Services (Add-on), you can combine existing services with spare time to create a separate complex service that clients can book a complete appointment with multiple services as any regular appointment. Each service included in the compound appointment will be performed by a relevant staff member who will only be reserved for their part of the service.\",\"tags\":[\"Booking form\",\"Staff & Teams\"],\"short\":\"Bundle several services into one bookable item.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(28, 21574466, 0, 0, 'https://www.booking-wp-plugin.com/demo/customer-information/', 'Customer Information', 'bookly-addon-customer-information', 'Need specific fields or records on a client profile in Bookly? Bookly Customer Information (Add-on) allows you to create multiple custom fields of different types that will appear on the Details step of the booking form. Once a booking is complete, the custom information entered by the client will be added to their profile in Bookly for future reference.', 'https://www.booking-wp-plugin.com/add-ons/add-custom-data-clients-profile/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-customer-information.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-customer-information.jpg', 29.00, '$9.95', 1692, 4.75, 8, '2018-03-13 06:10:12', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Need specific fields or records on a client profile in Bookly? Bookly Customer Information (Add-on) allows you to create multiple custom fields of different types that will appear on the Details step of the booking form. Once a booking is complete, the custom information entered by the client will be added to their profile in Bookly for future reference.\",\"tags\":[\"Customers\",\"Booking form\"],\"short\":\"Extra profile fields kept with every client.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22');
INSERT INTO `ebMMaZG04_bookly_shop` (`id`, `plugin_id`, `highlighted`, `priority`, `demo_url`, `title`, `slug`, `description`, `url`, `icon`, `image`, `price`, `sub_price`, `sales`, `rating`, `reviews`, `published`, `seen`, `visible`, `license`, `content`, `bundle_plugins`, `created_at`) VALUES
(29, 21574566, 0, 0, 'https://www.booking-wp-plugin.com/demo/ratings/', 'Ratings', 'bookly-addon-ratings', 'Gathering feedback from customers is crucial for businesses to understand areas where they can improve their services. With the Bookly Ratings (Add-on), you can request feedback from clients after each appointment. By encouraging customers to rate the service they received, you can continuously strive to maintain high professional standards and meet their expectations.', 'https://www.booking-wp-plugin.com/add-ons/add-staff-ratings/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-ratings.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-ratings.jpg', 29.00, '$9.95', 451, 0.00, 2, '2018-03-13 06:19:21', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Gathering feedback from customers is crucial for businesses to understand areas where they can improve their services. With the Bookly Ratings (Add-on), you can request feedback from clients after each appointment. By encouraging customers to rate the service they received, you can continuously strive to maintain high professional standards and meet their expectations.\",\"tags\":[\"Customers\",\"Marketing\"],\"short\":\"Collect reviews after the appointment ends.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(30, 21841764, 0, 0, 'https://www.booking-wp-plugin.com/demo/cart/', 'Cart', 'bookly-addon-cart', 'Do you want to boost your online sales even more? With With the Bookly Cart (Add-on), you can prompt your clients to book more appointments on your website. This feature enables clients to add multiple services to their cart and book them all in a single session. This way, clients can schedule additional future appointments with your business in one go. Also, the Cart step in Bookly can be customized to display summary information in a format that suits your needs.', 'https://www.booking-wp-plugin.com/add-ons/shopping-cart/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-cart.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-cart.jpg', 29.00, '$9.95', 2181, 5.00, 9, '2018-04-29 02:25:40', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you want to boost your online sales even more? With With the Bookly Cart (Add-on), you can prompt your clients to book more appointments on your website. This feature enables clients to add multiple services to their cart and book them all in a single session. This way, clients can schedule additional future appointments with your business in one go. Also, the Cart step in Bookly can be customized to display summary information in a format that suits your needs.\",\"tags\":[\"Booking form\",\"Payments\"],\"short\":\"Book several services in a single checkout.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(31, 21841828, 0, 0, 'https://www.booking-wp-plugin.com/demo/taxes/', 'Taxes', 'bookly-addon-taxes', 'Bookly Taxes (Add-on) makes it easy for you to include taxes in your service price. You can define multiple tax rates and apply them to selected services in Bookly. Once you’ve set up the tax rates, Bookly will automatically calculate and add the appropriate tax amount to the service price, resulting in a final price that includes taxes.', 'https://www.booking-wp-plugin.com/add-ons/automated-tax-calculations/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-taxes.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-taxes.jpg', 39.00, '$12.95', 810, 2.50, 4, '2018-04-29 02:29:54', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Taxes (Add-on) makes it easy for you to include taxes in your service price. You can define multiple tax rates and apply them to selected services in Bookly. Once you\\u2019ve set up the tax rates, Bookly will automatically calculate and add the appropriate tax amount to the service price, resulting in a final price that includes taxes.\",\"tags\":[\"Payments\",\"Automation\"],\"short\":\"Per-service tax rates, included or added on top.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(32, 21841856, 0, 0, 'https://www.booking-wp-plugin.com/demo/invoices/', 'Invoices', 'bookly-addon-invoices', 'Bookly Invoices (Add-on) allows you to automatically generate invoices for your clients upon ordered appointments in Bookly. You can choose to send payment requests when appointments are booked, approved, or received, and set a specific payment period. This feature allows you to quickly and easily collect payment from your clients and improve your cash flow.', 'https://www.booking-wp-plugin.com/add-ons/automatic-invoicing/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-invoices.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-invoices.jpg', 39.00, '$12.95', 1388, 4.60, 5, '2018-04-29 02:30:22', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Invoices (Add-on) allows you to automatically generate invoices for your clients upon ordered appointments in Bookly. You can choose to send payment requests when appointments are booked, approved, or received, and set a specific payment period. This feature allows you to quickly and easily collect payment from your clients and improve your cash flow.\",\"tags\":[\"Payments\",\"Automation\",\"Customers\"],\"short\":\"Automatic PDF invoices on your own template.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(33, 21841871, 0, 0, 'https://www.booking-wp-plugin.com/demo/google-maps-address/', 'Google Maps Address', 'bookly-addon-google-maps-address', 'The Bookly Google Maps Address (Add-on) streamlines the process of filling out address details in the booking form by using the Google Maps autocomplete service. Clients can quickly choose an address from the suggestions that appear as they type, minimizing errors and saving time. Address details entered in the Bookly booking form will be automatically saved in the Customers section for future reference.', 'https://www.booking-wp-plugin.com/add-ons/google-maps-autocomplete-service/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-google-maps-address.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-google-maps-address.jpg', 29.00, '$9.95', 575, 4.67, 3, '2018-04-29 02:45:11', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"The Bookly Google Maps Address (Add-on) streamlines the process of filling out address details in the booking form by using the Google Maps autocomplete service. Clients can quickly choose an address from the suggestions that appear as they type, minimizing errors and saving time. Address details entered in the Bookly booking form will be automatically saved in the Customers section for future reference.\",\"tags\":[\"Booking form\",\"Integrations\"],\"short\":\"Autocomplete and validate customer addresses.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(34, 22060579, 0, 0, 'https://www.booking-wp-plugin.com/demo/advanced-google-calendar/', 'Advanced Google Calendar', 'bookly-addon-advanced-google-calendar', 'With the Advanced Google Calendar (Add-on), you can enjoy a complete bidirectional synchronization between Bookly Calendar and Google Calendar. This ensures that all appointments can be viewed and managed seamlessly in both calendars. Bookings made through Bookly are automatically synced to your Google Calendar, and any new events, updates, or cancellations made in your Google Calendar are instantly reflected in Bookly.', 'https://www.booking-wp-plugin.com/add-ons/full-two-way-sync-google-calendar/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-advanced-google-calendar.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-advanced-google-calendar.jpg', 49.00, '$15.95', 3919, 4.53, 19, '2018-06-06 04:37:53', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"With the Advanced Google Calendar (Add-on), you can enjoy a complete bidirectional synchronization between Bookly Calendar and Google Calendar. This ensures that all appointments can be viewed and managed seamlessly in both calendars. Bookings made through Bookly are automatically synced to your Google Calendar, and any new events, updates, or cancellations made in your Google Calendar are instantly reflected in Bookly.\",\"tags\":[\"Calendar & Sync\",\"Integrations\",\"Automation\"],\"short\":\"Two-way sync with staff Google calendars.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":49,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":15.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(35, 22060627, 0, 0, 'https://www.booking-wp-plugin.com/demo/customer-cabinet/', 'Customer Cabinet', 'bookly-addon-customer-cabinet', 'Looking for a way to provide your clients with online access to their bookings? Bookly Customer Cabinet (Add-on) allows you to set up a secure, personal customer account on your website where clients can view and manage their appointments and profile information. This includes the ability to reschedule and cancel appointments, view payments, and update personal information.', 'https://www.booking-wp-plugin.com/add-ons/personal-customer-cabinet/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-customer-cabinet.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-customer-cabinet.jpg', 29.00, '$9.95', 2518, 4.29, 14, '2018-06-06 04:39:24', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Looking for a way to provide your clients with online access to their bookings? Bookly Customer Cabinet (Add-on) allows you to set up a secure, personal customer account on your website where clients can view and manage their appointments and profile information. This includes the ability to reschedule and cancel appointments, view payments, and update personal information.\",\"tags\":[\"Customers\",\"Automation\"],\"short\":\"Let customers reschedule and cancel themselves.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(36, 22060703, 0, 0, 'https://www.booking-wp-plugin.com/demo/custom-duration/', 'Custom Duration', 'bookly-addon-custom-duration', 'Bookly Custom Duration (Add-on) allows your clients to have more control over their bookings by choosing how long they would like their appointments to last. This feature is especially useful for services that may require more time than the default duration, such as meetings or conferences. When clients book services with flexible duration, they can select the length of their appointment at the beginning of the booking process in the Bookly form, and the price will be calculated accordingly.', 'https://www.booking-wp-plugin.com/add-ons/time-flexible-services/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-custom-duration.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-custom-duration.jpg', 29.00, '$9.95', 1847, 4.43, 7, '2018-06-06 04:42:30', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Custom Duration (Add-on) allows your clients to have more control over their bookings by choosing how long they would like their appointments to last. This feature is especially useful for services that may require more time than the default duration, such as meetings or conferences. When clients book services with flexible duration, they can select the length of their appointment at the beginning of the booking process in the Bookly form, and the price will be calculated accordingly.\",\"tags\":[\"Booking form\",\"Payments\"],\"short\":\"Let customers choose how long a session runs.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(37, 22060797, 0, 0, '', 'PayUbiz', 'bookly-addon-payu-biz', 'If you want to accept and manage online payments from your clients in India, PayUbiz is a popular payment gateway that can help. With the Bookly PayUbiz (Add-on), you can easily integrate PayUbiz method into your Bookly PRO booking form and offer your customers a convenient way to pay instantly for their appointments.', 'https://www.booking-wp-plugin.com/add-ons/payubiz/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-payu-biz.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-payu-biz.jpg', 29.00, '$9.95', 23, 0.00, 1, '2018-06-06 04:52:32', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"If you want to accept and manage online payments from your clients in India, PayUbiz is a popular payment gateway that can help. With the Bookly PayUbiz (Add-on), you can easily integrate PayUbiz method into your Bookly PRO booking form and offer your customers a convenient way to pay instantly for their appointments.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Card payments in India through PayUbiz.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(38, 22999600, 0, 0, 'https://www.booking-wp-plugin.com/demo/tasks/', 'Tasks', 'bookly-addon-tasks', 'Bookly Tasks (Add-on) offers a solution for businesses that provide services without requiring clients to select a specific day and time. With this feature, clients and administrators can create and manage a list of tasks or unscheduled appointments within the Bookly admin area. For instance, employees can set a task to arrange a meeting with a specific client, and once it’s done, they can schedule the date and time, which will automatically convert the task into an appointment.', 'https://www.booking-wp-plugin.com/add-ons/unlimited-list-tasks/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-tasks.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-tasks.jpg', 29.00, '$9.95', 573, 0.00, 2, '2018-12-12 00:17:51', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Tasks (Add-on) offers a solution for businesses that provide services without requiring clients to select a specific day and time. With this feature, clients and administrators can create and manage a list of tasks or unscheduled appointments within the Bookly admin area. For instance, employees can set a task to arrange a meeting with a specific client, and once it\\u2019s done, they can schedule the date and time, which will automatically convert the task into an appointment.\",\"tags\":[\"Staff & Teams\",\"Automation\"],\"short\":\"Assign and track work around each appointment.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(39, 22999632, 0, 0, 'https://www.booking-wp-plugin.com/demo/collaborative-services/', 'Collaborative Services', 'bookly-addon-collaborative-services', 'Do you offer services that involve two or more staff members working together or shared resources? With the Bookly Collaborative Services (Add-on), you can create and sell complex services that involve multiple employees and resources, while your clients easily book a single service they need. Whether your employees work together to provide a service or need to use shared resources in an appointment, Bookly will make sure everything is properly scheduled.', 'https://www.booking-wp-plugin.com/add-ons/share-rooms-equipment-employees/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-collaborative-services.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-collaborative-services.jpg', 39.00, '$12.95', 1004, 4.50, 4, '2018-12-12 00:22:29', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Do you offer services that involve two or more staff members working together or shared resources? With the Bookly Collaborative Services (Add-on), you can create and sell complex services that involve multiple employees and resources, while your clients easily book a single service they need. Whether your employees work together to provide a service or need to use shared resources in an appointment, Bookly will make sure everything is properly scheduled.\",\"tags\":[\"Staff & Teams\",\"Booking form\"],\"short\":\"Several providers on one appointment.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":39,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":12.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(40, 23324001, 0, 0, 'https://www.booking-wp-plugin.com/demo/custom-statuses/', 'Custom Statuses', 'bookly-addon-custom-statuses', 'If you need to manage your online bookings more efficiently and want to assign custom labels to your Bookly appointments, you can use Bookly Custom Statuses (Add-on). When editing an appointment, you can select a custom status from the list you created, allowing you to add more specific information to the appointment. You can also set up email notifications that correspond to each custom appointment status.', 'https://www.booking-wp-plugin.com/add-ons/use-custom-statuses/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-custom-statuses.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-custom-statuses.jpg', 29.00, '$9.95', 643, 5.00, 3, '2019-02-18 20:10:01', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"If you need to manage your online bookings more efficiently and want to assign custom labels to your Bookly appointments, you can use Bookly Custom Statuses (Add-on). When editing an appointment, you can select a custom status from the list you created, allowing you to add more specific information to the appointment. You can also set up email notifications that correspond to each custom appointment status.\",\"tags\":[\"Staff & Teams\",\"Automation\"],\"short\":\"Model your own workflow beyond the defaults.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(41, 23350952, 0, 0, '', 'Outlook Calendar', 'bookly-addon-outlook-calendar', 'Bookly Outlook Calendar (Add-on) enables a complete bidirectional synchronization between Bookly Calendar and Outlook Calendar, ensuring seamless management of appointments across both platforms. With this add-on, appointments made through Bookly will be automatically added to the linked Outlook Calendar, while updates, cancellations, and new events from Outlook Calendar will be immediately reflected in Bookly.', 'https://www.booking-wp-plugin.com/add-ons/outlook-calendar-sync/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-outlook-calendar.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-outlook-calendar.jpg', 49.00, '$15.95', 1228, 3.40, 5, '2019-02-21 23:33:34', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Outlook Calendar (Add-on) enables a complete bidirectional synchronization between Bookly Calendar and Outlook Calendar, ensuring seamless management of appointments across both platforms. With this add-on, appointments made through Bookly will be automatically added to the linked Outlook Calendar, while updates, cancellations, and new events from Outlook Calendar will be immediately reflected in Bookly.\",\"tags\":[\"Calendar & Sync\",\"Integrations\"],\"short\":\"Keep Outlook and Bookly schedules in step.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":49,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":15.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(42, 24219988, 0, 0, '', 'PayPal Checkout', 'bookly-addon-paypal-checkout', 'Bookly PayPal Checkout (Add-on) provides you with the ability to accept secure online payments at the time of booking through one of the most popular payment gateways. With this add-on, you can seamlessly integrate the PayPal payment option into your Bookly PRO booking form. By offering this convenient payment option to your customers, they can easily purchase your services with just a few clicks.', 'https://www.booking-wp-plugin.com/add-ons/paypal-checkout-payments/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-paypal-checkout.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-paypal-checkout.jpg', 29.00, '$9.95', 730, 0.00, 1, '2019-07-30 18:31:46', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly PayPal Checkout (Add-on) provides you with the ability to accept secure online payments at the time of booking through one of the most popular payment gateways. With this add-on, you can seamlessly integrate the PayPal payment option into your Bookly PRO booking form. By offering this convenient payment option to your customers, they can easily purchase your services with just a few clicks.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"The current PayPal flow, on-site and mobile ready.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(43, 29936495, 0, 0, 'https://www.booking-wp-plugin.com/demo/full/wp-admin/admin.php?page=bookly-discounts', 'Discounts', 'bookly-addon-discounts', 'Providing discounts is a proven method to attract customers and boost sales. Bookly Discounts (Add-on) enables you to create automatic conditional discounts based on various factors like the number of customers or services booked. Once the booking details meet the conditions you set, the discounted price will be automatically applied, and customers will see the reduced price instantly. ', 'https://www.booking-wp-plugin.com/add-ons/offer-conditional-discounts/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-discounts.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-discounts.jpg', 29.00, '$9.95', 435, 0.00, 0, '2021-01-05 01:18:25', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Providing discounts is a proven method to attract customers and boost sales. Bookly Discounts (Add-on) enables you to create automatic conditional discounts based on various factors like the number of customers or services booked. Once the booking details meet the conditions you set, the discounted price will be automatically applied, and customers will see the reduced price instantly.\",\"tags\":[\"Marketing\",\"Payments\",\"Automation\"],\"short\":\"Rule-based price cuts for services and periods.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(44, 34925755, 0, 0, '', 'Mailchimp', 'bookly-addon-mailchimp', 'Bookly Mailchimp (Add-on) offers a seamless integration between your Bookly booking system and your Mailchimp account, one of the most popular email marketing platforms available. With this integration, you can easily automate your email campaigns and build strong relationships with your customers. New customers in Bookly will be automatically added as new subscribers to your Mailchimp mailing list, allowing you to easily deliver targeted messages that drive sales and engagement.', 'https://www.booking-wp-plugin.com/add-ons/mailchimp-integration/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-mailchimp.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-mailchimp.jpg', 29.00, '$9.95', 186, 0.00, 2, '2021-11-24 03:10:56', 1, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Bookly Mailchimp (Add-on) offers a seamless integration between your Bookly booking system and your Mailchimp account, one of the most popular email marketing platforms available. With this integration, you can easily automate your email campaigns and build strong relationships with your customers. New customers in Bookly will be automatically added as new subscribers to your Mailchimp mailing list, allowing you to easily deliver targeted messages that drive sales and engagement.\",\"tags\":[\"Marketing\",\"Integrations\",\"Automation\"],\"short\":\"Sync customers into your Mailchimp audience.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(45, 20250716, 0, 0, 'https://www.booking-wp-plugin.com/demo/events/', 'Events', 'bookly-addon-events', 'Events (Add-on) allows you to create and manage events with various ticket types. Customers can buy tickets through a dedicated events form, while you easily track attendees in the admin panel.', 'https://www.booking-wp-plugin.com/add-ons/events/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-events.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-addon-events.png', 29.00, '$9.95', 84, 5.00, 1, '2026-09-24 14:13:53', 0, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"Events (Add-on) allows you to create and manage events with various ticket types. Customers can buy tickets through a dedicated events form, while you easily track attendees in the admin panel.\",\"tags\":[\"Calendar & Sync\",\"Marketing\",\"Booking form\"],\"badge\":\"Sale\",\"short\":\"Sell seats for classes and one-off events.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(46, 20251110, 2, 100, '', 'Bookly Business', 'bookly-bundle-business', 'All-in-one booking solution for growing businesses.\r\nBookly Business Bundle includes Bookly Pro and 16 powerful add-ons to help you manage appointments, teams, payments, and schedules more efficiently.\r\nGet advanced tools for custom booking forms, recurring appointments, staff management, online payments, special schedules, and more — everything you need to run your business smoothly with Bookly.', 'https://www.booking-wp-plugin.com/pricing/', 'https://cloud.bookly.pro/public_resources/images/bookly-bundle-business.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-bundle-business.png', 349.00, '$149.00', 223, 5.00, 1, '2026-09-24 14:13:53', 0, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"All-in-one booking solution for growing businesses.\\r\\nBookly Business Bundle includes Bookly Pro and 16 powerful add-ons to help you manage appointments, teams, payments, and schedules more efficiently.\\r\\nGet advanced tools for custom booking forms, recurring appointments, staff management, online payments, special schedules, and more \\u2014 everything you need to run your business smoothly with Bookly.\",\"badge\":\"Most popular\",\"short\":\"For growing teams that need more ways to book, pay, and manage.\",\"features\":[{\"body\":\"Custom fields, paid extras and durations of your own, so the form collects everything before the visit.\",\"title\":\"Advanced booking forms\"},{\"body\":\"Stripe and PayPal, with deposits when you take part of the price upfront and coupons when you give a discount.\",\"title\":\"Online payments at booking\"},{\"body\":\"Weekly or monthly repeats in one booking, and several attendees on a single time slot.\",\"title\":\"Recurring & group bookings\"},{\"body\":\"Individual schedules, holidays and exceptions, plus two-way sync with Google, Outlook and Apple calendars.\",\"title\":\"Staff schedules & calendars\"}],\"footnote\":\"%d add-ons in total, incl. Bookly Pro\",\"inherit\":\"Everything in Bookly Pro\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":349,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":5,\"amount\":449,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":149,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":5,\"amount\":199,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]}}}', '[7226091,21113970,21344225,21114146,15552320,22060579,18874038,17328208,18611122,20005540,21113860,22060627,19497634,17956131,21841764,19617518,22060703,23350952,20260727]', '2026-09-23 06:48:22'),
(47, 1, 0, 0, NULL, 'Bookly Booking Plugin – Responsive Appointment Booking and Scheduling', 'bookly', 'Bookly Plugin  is a great easy-to-use and easy-to-manage booking tool for service providers who think about their customers. The plugin supports a wide range of services provided by business and individuals who offer reservations through websites. Set up any reservation quickly, pleasantly and easily with Bookly!', 'https://codecanyon.net/item/bookly-booking-plugin-responsive-appointment-booking-and-scheduling/7226091', 'https://s3.envato.com/files/180750121/icon_80x80.png', '', 89.00, '', 21313, 4.59, 786, '2014-04-12 17:14:52', 0, 0, NULL, NULL, NULL, '2026-09-23 06:48:22'),
(49, 20251111, 1, 100, '', 'Bookly Ultimate', 'bookly-bundle-ultimate', 'The complete Bookly experience — every add-on, every feature, all in one.\r\nBookly Ultimate Bundle includes Bookly Pro and all existing Bookly add-ons, unlocking the full potential of the platform.\r\nEnjoy unlimited flexibility to automate online booking, manage complex schedules, process payments, handle customer relations, and integrate with any workflow — the most powerful version of Bookly ever made.', 'https://www.booking-wp-plugin.com/pricing/', 'https://cloud.bookly.pro/public_resources/images/bookly-bundle-ultimate.png', 'https://cloud.bookly.pro/public_resources/banners/bookly-bundle-ultimate.png', 599.00, '$249.00', 48, 5.00, 0, '2017-07-01 01:42:24', 0, 1, NULL, '{\"i18n\":{\"en\":{\"long\":\"The complete Bookly experience \\u2014 every add-on, every feature, all in one.\\r\\nBookly Ultimate Bundle includes Bookly Pro and all existing Bookly add-ons, unlocking the full potential of the platform.\\r\\nEnjoy unlimited flexibility to automate online booking, manage complex schedules, process payments, handle customer relations, and integrate with any workflow \\u2014 the most powerful version of Bookly ever made.\",\"badge\":\"ALL-IN\",\"short\":\"Everything you need to scale, with every add-on included.\",\"features\":[{\"body\":\"All 47 add-ons, and every one released while your license is active \\u2014 nothing to buy separately later.\",\"title\":\"Every add-on included\"},{\"body\":\"Ten gateways: Stripe, Square, both PayPal flows, Authorize.Net, 2Checkout, Mollie, Payson and PayU for Latin America and India.\",\"title\":\"More payment options\"},{\"body\":\"One license across a WordPress network, and venues with their own staff, hours and prices.\",\"title\":\"Multiple sites & locations\"},{\"body\":\"Customer groups and cabinets, ratings, invoices, taxes, gift cards, packages and waiting lists.\",\"title\":\"The full customer management toolkit\"}],\"footnote\":\"Every add-on, plus future releases\",\"adds_suffix\":\" & priority support\",\"inherit\":\"Everything in Bookly Business\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":199,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":20,\"amount\":599,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":100,\"amount\":799,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":159,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":20,\"amount\":249,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null},{\"quantity\":100,\"amount\":299,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]}}}', '[7226091,13903524,15552320,17328208,17367838,17457141,17956131,18611122,18704535,18874038,19497634,19617518,20005540,20685954,20917406,20952783,21113698,21113750,21113860,21113970,21114042,21114096,21114146,21344225,21344290,21344354,21574371,21574466,21574566,21841764,21841828,21841856,21841871,22060579,22060627,22060703,22060797,22999600,22999632,23324001,23350952,24219988,29936495,34925755,20250716,20260727,20260519,20260518]', '2026-09-23 06:48:22'),
(50, 20260518, 0, 0, '', 'Square', 'bookly-addon-square', 'With Square Payments enabled, you can seamlessly integrate the Square payment gateway into your Bookly booking form, allowing clients to conveniently pay for your services online.', 'https://www.booking-wp-plugin.com/add-ons/square/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-square.png', '', 29.00, '$9.95', 105, 5.00, 1, '2026-09-24 14:13:53', 0, 0, NULL, '{\"i18n\":{\"en\":{\"long\":\"With Square Payments enabled, you can seamlessly integrate the Square payment gateway into your Bookly booking form, allowing clients to conveniently pay for your services online.\",\"tags\":[\"Payments\",\"Integrations\"],\"short\":\"Take Square payments without leaving the form.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(51, 20260519, 0, 0, '', 'Gift Cards', 'bookly-addon-gift-cards', 'With the Gifts Cards feature enabled, you can issue vouchers and offer them to your clients as a payment method in the Bookly booking form.', 'https://www.booking-wp-plugin.com/add-ons/gift-cards/', 'https://cloud.bookly.pro/public_resources/images/bookly-addon-gift-cards.png', '', 29.00, '$9.95', 122, 5.00, 1, '2026-09-24 14:13:53', 0, 0, NULL, '{\"i18n\":{\"en\":{\"long\":\"With the Gifts Cards feature enabled, you can issue vouchers and offer them to your clients as a payment method in the Bookly booking form.\",\"tags\":[\"Marketing\",\"Payments\"],\"badge\":\"New\",\"short\":\"Sell and redeem gift cards for any service.\"}},\"shared\":{\"prices\":{\"lifetime\":[{\"quantity\":1,\"amount\":29,\"list_amount\":null,\"currency\":\"USD\",\"period\":null,\"on_sale\":false,\"sale_ends_at\":null}],\"subscription\":[{\"quantity\":1,\"amount\":9.95,\"list_amount\":null,\"currency\":\"USD\",\"period\":\"year\",\"on_sale\":false,\"sale_ends_at\":null}]},\"requires\":\"bookly-addon-pro\"}}', NULL, '2026-09-23 06:48:22'),
(52, 20260727, 0, 0, NULL, 'Bookly Apple Calendar (Add-on)', 'bookly-addon-apple-calendar', 'Keep your schedules always up to date with seamless synchronization between your Bookly Calendar and Apple Calendar. Bookly Apple Calendar (Add-on) helps you stay organized, avoid scheduling conflicts, and never miss important appointments by ensuring all calendar data is continuously synced.', 'https://www.booking-wp-plugin.com/add-ons/apple-calendar-sync/', 'https://i.bookly.info/main/products/apple-calendar-icon.png', 'https://i.bookly.info/main/products/bookly-apple-calendar-banner-590.png', 29.00, '$9.95', 17, 5.00, 0, '2026-09-23 06:48:22', 0, 1, NULL, NULL, NULL, '2026-09-23 06:48:22');
