(42, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(43, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(44, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(45, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(46, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(47, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(48, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(49, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(50, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(51, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(52, 'woo-activation-survey-blockers-22AUG23', 'info', 'en_US', 'How can we help you get that first sale?', 'Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(53, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(54, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(55, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(56, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(57, 'checkout_survey_new_users', 'survey', 'en_US', 'We\'d like your feedback on WooCommerce checkout', 'Your feedback is essential for us to improve the WooCommerce checkout and increase your conversion rate, turning more visitors into customers. Answer a few questions to help us understand your experience. It shouldn\'t take more than 5 minutes of your time.', '{}', 'pending', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(58, 'checkout_survey_new_users_no_orders', 'survey', 'en_US', 'We\'d like your feedback on WooCommerce checkout', 'Your feedback is essential for us to improve the WooCommerce checkout and increase your conversion rate, turning more visitors into customers. Answer a few questions to help us understand your experience. It shouldn\'t take more than 5 minutes of your time.', '{}', 'unactioned', 'woocommerce.com', '2024-05-13 07:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(99, 'WooCommerce-Stripe-Gateway-Update-April-2025', 'update', 'en_US', 'Action required: Update WooCommerce Stripe Gateway to v9.4.1', '<strong>An important update for WooCommerce Stripe Payment Gateway has been released</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. Please update as soon as possible for optimal store performance. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-19 04:59:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(60, 'woocommerce-payfast-may-2024-update-needed', 'update', 'en_US', 'An important update is required for the Payfast Payment Gateway', '<strong>Please update to the latest version of the Payfast Payment Gateway for WooCommerce immediately to address a security vulnerability</strong>. This update is required to ensure that your transactions continue to process.', '{}', 'pending', 'woocommerce.com', '2024-05-15 05:13:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(61, 'wc-update-db-reminder', 'update', 'en_US', 'Actualización de la base de datos de WooCommerce terminada', 'Actualización de la base de datos de WooCommerce completa. ¡Gracias por actualizar a la última versión!', '{}', 'actioned', 'woocommerce-core', '2024-05-15 11:21:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(63, 'wc-admin-mobile-app', 'info', 'en_US', 'Instala la aplicación móvil WooCommerce', 'Instala la aplicación móvil de WooCommerce para gestionar pedidos, recibir avisos de ventas y ver métricas clave – allí donde estés.', '{}', 'unactioned', 'woocommerce-admin', '2024-05-16 14:39:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(62, 'wc-admin-wc-helper-connection', 'info', 'en_US', 'Conectar con WooCommerce.com', 'Conéctate para recibir avisos y actualizaciones importantes de productos.', '{}', 'unactioned', 'woocommerce-admin', '2024-05-15 14:32:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(64, 'wc-admin-customizing-product-catalog', 'info', 'en_US', 'Cómo personalizar tu catálogo de productos', 'Quieres que tu catálogo de productos y tus imágenes tengan un aspecto estupendo y estén en consonancia con tu marca. Esta guía te dará todos los consejos que necesitas para que tus productos se vean bien en tu tienda.', '{}', 'unactioned', 'woocommerce-admin', '2024-05-18 05:10:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(65, 'wc-admin-onboarding-payments-reminder', 'info', 'en_US', '¡Empieza a aceptar pagos en tu tienda!', 'Acepta pagos mediante el proveedor adecuado para ti - elige entre más de 100 pasarelas de pago para WooCommerce.', '{}', 'unactioned', 'woocommerce-admin', '2024-05-19 05:10:21', NULL, 0, 'plain', '', 0, 0, 'info'),
(66, 'wc-admin-usage-tracking-opt-in', 'info', 'en_US', 'Ayuda a WooCommerce a mejorar con el seguimiento de uso', 'Recopilar datos de uso nos permite mejorar WooCommerce. Se tendrá en cuenta a tu tienda a medida que evaluamos nuevas características, juzgamos la calidad de una actualización o determinamos si una mejora tiene sentido. Siempre puedes visitar los <a href=\"https://reservas.abanilla.es/wp-admin/admin.php?page=wc-settings&#038;tab=advanced&#038;section=woocommerce_com\" target=\"_blank\">Ajustes</a> y elegir dejar de compartir datos. <a href=\"https://woocommerce.com/usage-tracking?utm_medium=product\" target=\"_blank\">Lee más</a> sobre los datos que recopilamos.', '{}', 'unactioned', 'woocommerce-admin', '2024-05-21 05:27:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(67, 'wc-admin-orders-milestone', 'info', 'en_US', 'Primer pedido recibido', '¡Felicidades por conseguir tu primer pedido! Ahora es un buen momento para aprender cómo gestionar tus pedidos.', '{\"current_milestone\":1}', 'unactioned', 'woocommerce-admin', '2024-05-30 14:38:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(68, 'mailchimp_q2_2024', 'marketing', 'en_US', 'Level up your marketing to boost sales', 'Looking for a smart way to kickstart your growth? Mailchimp’s best-in-class email marketing empowers you to create and automate precisely targeted SMS and email campaigns and build long-term relationships with your audience. Enhance your customer experience, track sales, and more by connecting your store to Mailchimp.', '{}', 'pending', 'woocommerce.com', '2024-06-05 05:06:59', NULL, 0, 'plain', '', 0, 0, 'info'),
(69, 'WC-order-attribution-update-June-2024', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>An important security update for WooCommerce has been released</strong>. It is recommended that you update as quickly as possible.', '{}', 'unactioned', 'woocommerce.com', '2024-06-11 04:57:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(70, 'checkout_block_update_july_2024', 'marketing', 'en_US', 'UPDATE: The checkout block is getting an upgrade!', 'We’re improving the checkout block in 2024, starting with WooCommerce 9.0, launching on June 18! The latest release includes streamlined order summary with sticky functionality, better address form layout, and other enhancements to boost conversion.', '{}', 'pending', 'woocommerce.com', '2024-06-19 05:05:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(71, 'bfcm-survey-jul2024', 'marketing', 'en_US', 'Complete our holiday survey and get a $30 coupon', 'We want to understand how you prepare your store for Black Friday/Cyber Monday and the holidays.\r\n\r\nComplete our 10-minute survey and get $30 USD off an extension from our official Marketplace. Hurry, the survey closes July 15.', '{}', 'pending', 'woocommerce.com', '2024-07-04 05:14:21', NULL, 0, 'plain', '', 0, 0, 'info'),
(72, 'stripe_newcheckout_q3_2024', 'marketing', 'en_US', 'Upgrade your Stripe checkout for even more payment options', 'Boost sales, increase order value, and reach new customers with the new checkout from Stripe. Support 23 payment methods, including buy now, pay later methods like Klarna, Afterpay, and Affirm; Bancontact in Europe and Alipay in Asia; and Link, an accelerated checkout experience that autofills payment information.', '{}', 'pending', 'woocommerce.com', '2024-07-05 05:19:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(73, 'klaviyo_q4_2024', 'marketing', 'en_US', 'Need a marketing solution to help you sell more?', 'Over 13,000 brands use Klaviyo to grow faster. You can drive 46x ROI with their personalized email, SMS, forms, and product reviews. Start for free today.', '{}', 'pending', 'woocommerce.com', '2024-08-01 05:15:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(74, 'wc-admin-real-time-order-alerts', 'info', 'en_US', 'Recibe alertas de pedidos en tiempo real en cualquier lugar', 'Recibe avisos sobre la actividad de la tienda, incluidos nuevos pedidos y valoraciones de productos directamente en tus dispositivos móviles con la aplicación Woo.', '{}', 'unactioned', 'woocommerce-admin', '2024-08-12 05:14:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(75, 'wnww-recap-july', 'marketing', 'en_US', 'Powerful updates and upgrades in WooCommerce', 'Have you seen all the latest from Woo? Check out our recent roundup for a look at the newest features, extensions, and insights making WooCommerce perform better than ever.', '{}', 'pending', 'woocommerce.com', '2024-08-14 05:18:13', NULL, 0, 'plain', '', 0, 0, 'info'),
(76, 'bfcm2024-landing-page', 'marketing', 'en_US', 'The best way to prepare for holiday success', 'The upcoming holiday season is the busiest time of the year for many online stores. We want to help you make the most of it with an early gift: our first-ever Black Friday Cyber Monday Trends Report. It\'s full of stats, trends, and recommendations to knock your holiday socks off!', '{}', 'pending', 'woocommerce.com', '2024-09-05 05:15:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(77, 'stripe_securityupdate_q3_2024', 'update', 'en_US', 'Security update required for your Stripe extension', 'To continue securely accepting payments, you must update your Stripe extension to at least version 8.6, re-authenticate, and turn on the new checkout experience. Review the documentation for instructions on how to make the necessary changes from your WooCommerce dashboard.', '{}', 'pending', 'woocommerce.com', '2024-09-19 05:18:13', NULL, 0, 'plain', '', 0, 0, 'info'),
(78, 'paypal_migration_Q3_2024', 'marketing', 'en_US', 'Estás usando una versión obsoleta de PayPal.', 'No dejes escapar las posibles ventas esta temporada navideña: mejora la experiencia de pago de tu tienda con la nueva extensión de PayPal Payments. Permite a los clientes pagar con PayPal, Paga en 3, tarjetas de crédito y débito, Apple Pay, Google Pay y métodos de pago específicos para cada país, entre otras opciones.', '{}', 'pending', 'woocommerce.com', '2024-10-04 05:09:59', NULL, 0, 'plain', '', 0, 0, 'info'),
(79, 'paypal_migration_Q3_2024_v2', 'marketing', 'en_US', 'Estás usando una versión obsoleta de PayPal.', 'No dejes escapar las posibles ventas esta temporada navideña: mejora la experiencia de pago de tu tienda con la nueva extensión de PayPal Payments. Permite a los clientes pagar con PayPal, Paga en 3, tarjetas de crédito y débito, Apple Pay, Google Pay y métodos de pago específicos para cada país, entre otras opciones.', '{}', 'pending', 'woocommerce.com', '2024-10-31 06:03:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(80, 'mollie_q4_2024', 'marketing', 'en_US', 'Special offer: Zero transaction fees for your first month with Mollie', 'With seamless checkout, flexible financing, and 30+ local and global payment methods, Mollie is the all-in-one payment solution that enhances the customer experience and helps your business grow. Start your account today and enjoy ZERO transaction fees for the first month. Ts&amp;Cs apply.', '{}', 'unactioned', 'woocommerce.com', '2024-11-01 06:02:11', NULL, 0, 'plain', '', 0, 0, 'info'),
(81, 'wc-admin-manage-orders-on-the-go', 'info', 'en_US', 'Gestiona tus pedidos desde cualquier lugar', 'Busca pedidos, información de clientes y procesa reembolsos en un clic con la app de Woo.', '{}', 'unactioned', 'woocommerce-admin', '2024-11-10 05:58:16', NULL, 0, 'plain', '', 0, 0, 'info'),
(82, 'Renewal_notification_emails_Woosubscriptions_Nov2024', 'marketing', 'en_US', 'WooCommerce Subscriptions just got even better', 'You can now send automatic email reminders to customers before their subscriptions renew or expire. To enable this for your store, update to the latest version of WooCommerce Subscriptions (don\'t forget to make a backup first) and follow the steps linked below.', '{}', 'pending', 'woocommerce.com', '2024-11-19 05:58:59', NULL, 0, 'plain', '', 0, 0, 'info'),
(83, 'paypal_promo_Q4_2024', 'marketing', 'en_US', 'Add PayPal to your existing checkout this holiday season', 'Drive conversion and give customers more confidence to buy when you complement your checkout with PayPal, Venmo, Pay Later, and more. Attract new shoppers and give them a streamlined buying experience with Fastlane, PayPal’s fast and simple guest checkout.', '{}', 'pending', 'woocommerce.com', '2024-11-28 05:55:50', NULL, 0, 'plain', '', 0, 0, 'info'),
(84, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2024-12-04 06:01:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(85, 'usps-mail-service-to-canada-suspended-dec-2024', 'update', 'en_US', 'Please note: USPS Mail Service to Canada Suspended', 'The United States Postal Service has temporarily suspended mail service to Canada due to the ongoing Canadian postal workers\' strike. USPS is asking users to refrain from mailing items to Canada at this time.', '{}', 'pending', 'woocommerce.com', '2024-12-05 05:54:45', NULL, 0, 'plain', '', 0, 0, 'info'),
(86, 'Announce-UPS-WCShipping-Dec2024', 'marketing', 'en_US', 'WooCommerce Shipping now supports select UPS services', 'Give customers the power and reliability of UPS, directly from your dashboard. Access discounted rates, convenient shipping options, and fast, on-time delivery with UPS on WooCommerce Shipping — and stay tuned for UPS® Ground Saver rates coming in 2025.', '{}', 'pending', 'woocommerce.com', '2024-12-13 05:55:49', NULL, 0, 'plain', '', 0, 0, 'info'),
(87, 'account-creation-after-checkout-dec2024', 'marketing', 'en_US', 'Offer account creation after checkout', 'Your customers can now create accounts after they check out on block-based themes. Enable the new “After checkout” block in your account settings and enjoy smoother guest checkout, better conversion, and more repeat business.', '{}', 'pending', 'woocommerce.com', '2024-12-19 05:54:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(88, 'woocommerce-analytics-order-attribution-promotions-december-2024', 'marketing', 'en_US', 'Discover what drives your sales', 'Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.', '{}', 'pending', 'woocommerce.com', '2024-12-24 05:53:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(89, 'affirm_promo_Q1_2025', 'marketing', 'en_US', 'Save up to 50% on merchant fees with Affirm', 'Kickstart the year with buy now, pay later and get merchant rates as low as 2.9% + 30¢ per transaction for 30 days. Download the extension and complete your application from your WooCommerce dashboard by February 19, 2025 to claim the offer. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2025-01-21 05:51:30', NULL, 0, 'plain', '', 0, 0, 'info'),
(90, 'new-woo-brand-announcement-feb4-2025', 'marketing', 'en_US', 'Meet the new Woo', 'WooCommerce has a new look, but underneath, we’re still the same customizable, open-source ecommerce platform you know and love. Plus, we’ve got some major improvements to our platform and product on the way.', '{}', 'pending', 'woocommerce.com', '2025-02-05 05:54:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(91, 'wc-admin-performance-on-mobile', 'info', 'en_US', 'Haz seguimiento del rendimiento de tu tienda en tu móvil', 'Supervisa tus ventas y los productos de alto rendimiento con la aplicación de Woo. ', '{}', 'unactioned', 'woocommerce-admin', '2025-02-08 05:48:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(92, 'paypal_bnpl_au_promo_Q1_2025', 'marketing', 'en_US', 'Australian shoppers can Pay in 4 with PayPal', 'Enable Pay in 4 messaging to let Australian customers know that they can pay over time while you get paid up front and in full. Pay in 4 is included in PayPal Payments at no additional cost. Eligible buyers can pay in four interest-free payments for purchases of $30 to $2,000 AUD. Terms apply.', '{}', 'pending', 'woocommerce.com', '2025-02-12 02:20:11', NULL, 0, 'plain', '', 0, 0, 'info'),
(93, 'stripe_stripetax_q1_2025', 'marketing', 'en_US', 'Say goodbye to your tax woes', 'Stripe Tax automatically applies the correct sales tax, VAT, or GST, saving time while keeping you compliant. And with simple automatic filing, you can stop stressing at tax time and focus on growing instead.', '{}', 'pending', 'woocommerce.com', '2025-02-19 09:47:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(94, 'printful_promo_q1_2025', 'marketing', 'en_US', 'New: sell print-on-demand products, risk-free', 'Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.', '{}', 'pending', 'woocommerce.com', '2025-02-26 05:53:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(95, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2025-03-04 05:49:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(96, 'woo-marketplace-two-year-subscriptions-rin-2025-03-17', 'marketing', 'en_US', 'Save 20% on new two-year subscriptions', 'We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.', '{}', 'pending', 'woocommerce.com', '2025-03-17 05:51:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(97, 'viva_wallet_migration_q1_2025', 'update', 'en_US', 'Switch to the new Viva.com Smart Checkout', 'The Viva Wallet extension is no longer being updated and improved. To get the best Viva.com experience, move to the new Smart Checkout. It’s fast, secure, and fully compatible with the latest WooCommerce features.', '{}', 'pending', 'woocommerce.com', '2025-04-04 04:57:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(98, 'stripe_orderstatus_bug_q2_2025', 'update', 'en_US', 'Action Required: Update Order Status Manager', 'Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.', '{}', 'pending', 'woocommerce.com', '2025-04-04 04:57:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(100, 'WooCommerce-Stripe-Gateway-Update-Info-April-2025', 'update', 'en_US', 'WooCommerce Stripe Gateway has been updated to v9.4.1', '<strong>WooCommerce Stripe Payment Gateway was recently updated</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. No further action is required. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory post </a>for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-19 04:59:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(101, 'klaviyo_q2_2025', 'marketing', 'en_US', 'Tailor your marketing with data-driven automation', 'Deliver personalized experiences at scale, simplify your stack, and make your data work for you using Klaviyo’s best-in-class marketing extension for Woo. With advanced segmentation based on actual customer behavior, you can send email and SMS messages that drive revenue and increase loyalty — without adding complexity', '{}', 'pending', 'woocommerce.com', '2025-04-30 05:04:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(102, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2025-05-05 05:00:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(103, 'payson-retirement-2025', 'update', 'en_US', 'Payson Form Retirement', 'Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.', '{}', 'pending', 'woocommerce.com', '2025-05-12 23:57:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(104, 'wc-admin-edit-products-on-the-move', 'info', 'en_US', 'Edita productos sobre la marcha', 'Edita y crea nuevos productos desde tus dispositivos móviles con la aplicación de Woo', '{}', 'unactioned', 'woocommerce-admin', '2025-05-14 05:07:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(105, 'paypal_q2_2025', 'marketing', 'en_US', 'Power up sales with Pay Later messaging', 'Help increase your sales and grow cart sizes by letting customers know they have flexible payment options. Merchants see up to an 11% sales lift when they add Pay Later messaging — plus, it integrates seamlessly with your PayPal checkout.', '{}', 'pending', 'woocommerce.com', '2025-05-22 05:02:59', NULL, 0, 'plain', '', 0, 0, 'info'),
(106, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2025-05-30 05:01:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(107, 'tento_q2_2025', 'marketing', 'en_US', 'Get your free business credit score', 'Strong business credit is the key to better deals, stronger partnerships, and sustainable growth. Tento Business Credit Monitoring helps you catch risks early, secure better financing, and fuel smarter growth — with no impact to your credit.', '{}', 'pending', 'woocommerce.com', '2025-06-04 05:02:50', NULL, 0, 'plain', '', 0, 0, 'info'),
(108, 'wc-admin-email-improvements', 'info', 'en_US', '¡Los correos electrónicos de tu tienda se han actualizado!', 'Hemos realizado algunas mejoras interesantes en tus plantillas de correo electrónico, incluidos diseños modernos y fáciles de usar para los compradores y nuevas opciones de personalización. Y si utilizas un tema de bloques puedes sincronizar automáticamente los estilos de tus temas. Accede a tus ajustes de correo electrónico para ver los nuevos cambios.', '{}', 'unactioned', 'woocommerce-admin', '2025-06-11 05:00:06', NULL, 0, 'plain', '', 0, 0, 'info');
INSERT INTO `ebMMaZG04_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES
(109, 'woopayments-multibanco-alipay-wechat-launch-2025-06-23', 'marketing', 'en_US', 'Multibanco, AliPay and WeChat now available in WooPayments', 'Multibanco, AliPay, and WeChat Pay are now available in WooPayments! Offer trusted local payment methods to customers in key global markets and boost international sales. Geo restrictions apply.', '{}', 'pending', 'woocommerce.com', '2025-06-24 05:04:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(110, 'woopayments-new-lpms-2025-06-30', 'marketing', 'en_US', 'Get the POS built specifically for Woo stores', 'Introducing WooCommerce POS, our new point-of-sale solution built to get you up and running quickly with in-person sales. Search products, scan barcodes, apply coupons, and send email receipts — right in the WooCommerce mobile app, with all of your online and physical sales synced in real time — no extra setup required', '{}', 'pending', 'woocommerce.com', '2025-07-01 05:02:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(111, 'tiktok-webinar-promo-july2025', 'marketing', 'en_US', 'You\'re Invited: TikTok for WooCommerce Webinar', 'Join us for a free webinar with our friends at TikTok on Tuesday, July 8, at 4 pm UTC. We\'ll cover creative tips and best practices for making content that turns views into sales.', '{}', 'pending', 'woocommerce.com', '2025-07-01 05:02:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(112, 'woopayments-grabpay-launch-2025-07-07', 'marketing', 'en_US', 'GrabPay now available in WooPayments', 'Offer GrabPay through WooPayments and make checkout easier for customers across Southeast Asia. Enable it today and expand your reach with a payment method they know and trust.', '{}', 'pending', 'woocommerce.com', '2025-07-07 23:53:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(113, 'BFCM-25-Survey', 'marketing', 'en_US', 'You’re invited: Take our quick BFCM survey and get 25% off', 'We’re gathering insights on how businesses prepare for peak sales moments like Black Friday and Cyber Monday — so we can better support you. Take our quick 8-minute survey to share your thoughts and get 25% off your next WooCommerce extension as a thank you.', '{}', 'pending', 'woocommerce.com', '2025-07-15 05:05:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(114, 'woohoo10-coupon', 'marketing', 'en_US', 'Celebrate and save with WooCommerce 10.0', 'To mark this milestone release, get 10% off extensions and themes in the official Woo Marketplace. Use code WOOHOO10 at checkout to save on essential tools that help grow your business. Offer ends August 15, 2025. Terms and conditions apply.', '{}', 'unactioned', 'woocommerce.com', '2025-07-22 01:25:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(115, 'paypaladvantage_q3_2025', 'marketing', 'en_US', 'Add PayPal Checkout and earn up to $1,000*', 'PayPal Checkout can boost conversion by up to 46% and average order value by up to 62% with no disruption to your checkout. New US merchants who activate by August 31 save 25% on transaction fees for 6 months. Excludes Venmo. Terms apply.*', '{}', 'pending', 'woocommerce.com', '2025-07-23 04:58:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(116, 'stripe_optimizedcheckout_upgrade_q3_2025', 'marketing', 'en_US', 'Upgrade for a faster, more flexible Stripe checkout', 'You\'re not on the latest WooCommerce Stripe Payment Gateway version. Upgrade to version 9.8 to access Stripe\'s Optimized Checkout Suite and leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-16 04:53:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(117, 'stripe_optimizedcheckout_enable_q3_2025', 'marketing', 'en_US', 'Unlock dynamic payments and sell more', 'You’re on the latest WooCommerce Stripe Payment Gateway — now unlock its full potential by enabling the Optimized Checkout Suite. It uses AI models to dynamically surface the most relevant payment methods for each customer, helping you boost conversions.', '{}', 'pending', 'woocommerce.com', '2025-08-16 04:53:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(118, 'stripe_optimizedcheckout_promotion_q3_2025', 'marketing', 'en_US', 'Upgrade to Stripe for a faster, more flexible checkout', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-16 04:53:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(119, 'woo-subscription-gifting-bundling-2025-08-18', 'marketing', 'en_US', 'Grow recurring revenue with gifting', 'WooCommerce Subscriptions now includes gifting. Customers can buy subscriptions for others, helping you reach new shoppers and grow recurring revenue with less effort. Update to the latest version of Subscriptions (7.8.0) to start offering gifting.', '{}', 'pending', 'woocommerce.com', '2025-08-20 04:55:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(120, 'stripe_optimizedcheckout_competitors_q3_2025', 'marketing', 'en_US', 'Upgrade to the official WooCommerce Stripe Payment Gateway', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Use AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click checkout with Link.', '{}', 'pending', 'woocommerce.com', '2025-08-29 04:52:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(121, 'UPS-promo-RIN-WCS-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-12 05:12:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(122, 'UPS-promo-RIN-WCST-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-12 05:12:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(123, 'square_ordersync_upgrade_q3_2025', 'marketing', 'en_US', 'You asked, we delivered — order sync is here for Square', 'Update your Square extension to v5.0 to access <a href=\"https://woocommerce.com/document/woocommerce-square/sync-settings/sync-orders-between-woocommerce-and-square/\">automatic order syncing</a>. Manage your online sales in Square, keep reports accurate, and save time with order updates visible across both platforms.', '{}', 'pending', 'woocommerce.com', '2025-09-12 05:12:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(124, 'klaviyo_q3_2025', 'marketing', 'en_US', 'Smarter marketing starts with Woo x Klaviyo', 'Personalize every customer interaction with Klaviyo, Woo\'s preferred marketing automation solution. Advanced segmentation based on real customer behavior lets you create email and SMS campaigns focused on driving loyalty and revenue. So you can grow sales while simplifying your stack.', '{}', 'pending', 'woocommerce.com', '2025-09-17 04:52:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(125, 'pinterest_q3_20252', 'marketing', 'en_US', 'More visibility, smarter campaigns', 'Connect your store to Pinterest via the Conversions API, a new feature in the latest version of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Get started today — connect and sync your catalog using the Conversions API.', '{}', 'pending', 'woocommerce.com', '2025-09-24 01:17:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(126, 'pinterest_q4_2025', 'marketing', 'en_US', 'Maximize conversions with Pinterest', 'Connect your store to Pinterest via the Conversions API, now part of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Sync your catalog and create your first ad today.', '{}', 'pending', 'woocommerce.com', '2025-10-22 04:58:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(127, 'paypaladvantage_q4_2025', 'marketing', 'en_US', 'PayPal Checkout offer: Get 40% back on fees for 3 months', 'Download and activate PayPal Payments in your WooCommerce admin, then complete your first transaction by 15 December 2025 to get 40% back on PayPal transaction fees — up to £2,000 for 3 months. PayPal Checkout works with your existing checkout. See terms: paypal.com/uk/campaign/paypalmerchantpromotion/terms.', '{}', 'pending', 'woocommerce.com', '2025-11-05 05:53:14', NULL, 0, 'plain', '', 0, 0, 'info'),
(128, 'reddit_q4_2025', 'marketing', 'en_US', 'New: Reach high-intent shoppers on Reddit', 'Sync your catalog and pixel with Reddit for WooCommerce. Launch your ads faster on Reddit and connect with their 400M+ weekly active users and shoppers who turn to this platform for authentic conversations and recommendations.', '{}', 'pending', 'woocommerce.com', '2025-11-14 05:52:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(129, 'bfcm_general_sale_q4_2025', 'marketing', 'en_US', 'Save up to 40% on extensions and themes', 'For a limited time, take up to 40% off nearly everything in our Marketplace. It’s the perfect moment to give your store a holiday boost and level up for 2026. Sale ends December 2, 2025, at 14:00 UTC.', '{}', 'pending', 'woocommerce.com', '2025-11-20 05:48:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(130, 'paypal-carding-recaptcha-dec-25', 'update', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'pending', 'woocommerce.com', '2025-12-04 05:59:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(131, 'Googleupdate_q4_2025', 'marketing', 'en_US', 'Make every ad dollar count this holiday season', 'Google for WooCommerce now includes Budget Recommendations. Install the latest version and get personalized suggestions on where to optimize campaign budgets to reach more holiday shoppers this season.', '{}', 'pending', 'woocommerce.com', '2025-12-05 23:38:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(132, 'holiday_shipping_deadlines_WCST_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 05:49:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(133, 'holiday_shipping_deadlines_WCS_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 05:49:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(134, 'snap_q4_2025', 'marketing', 'en_US', 'New: Reach a new audience on Snapchat', '88% of Snapchatters love to shop, and 40% aren\'t active on other social platforms. Connect with them and grow your business using Snapchat for WooCommerce, our new official extension. Sync your products, launch ad campaigns, and track results — all from your Woo dashboard.', '{}', 'pending', 'woocommerce.com', '2025-12-20 05:48:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(135, 'stripe_agenticcommerce_3PDS_q4_2025', 'marketing', 'en_US', 'Get more from Stripe with the official extension', 'Switch to the official extension co-developed with Stripe for the latest features and best performance. Get access to personalized checkout options, early support for AI shopping through Stripe’s <a href=\"https://woocommerce.com/posts/stripe-agentic-commerce-suite-for-woocommerce/\">Agentic Commerce Suite</a>, and more.', '{}', 'pending', 'woocommerce.com', '2025-12-20 05:48:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(136, 'WC10.4.3-security-update-12-22-2025', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Please update to WooCommerce 10.4.3 to resolve a security issue.</strong> This update addresses an issue with the WooCommerce Store API that may have made guest order information visible to other logged in users. See the <a href=\"https://developer.woocommerce.com/2025/12/22/store-api-vulnerability-patched-in-woocommerce-8-1/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-12-23 05:53:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(137, 'downloads-sub-Jan2026-RIN', 'marketing', 'en_US', 'WooCommerce Subscription Downloads is now part of WooCommerce Subscriptions', 'WooCommerce Subscriptions now allows you to include simple and variable downloadable products with your subscriptions. Streamline your subscription downloads by updating to the latest version of WooCommerce Subscriptions today.', '{}', 'pending', 'woocommerce.com', '2026-01-08 05:56:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(138, 'paypal-carding-recaptcha-jan-26', 'update', 'en_US', 'Fraud protection is now required — enable today', 'Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.', '{}', 'pending', 'woocommerce.com', '2026-01-13 05:49:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(139, 'USPS API Migration_RIN_Jan2026', 'marketing', 'en_US', 'Upgrade to USPS Shipping REST API by January 25', 'USPS is retiring the legacy Web Tools API on January 25, 2026. If you’re using the USPS Shipping Method extension with the legacy API, live USPS shipping rates will longer be shown at checkout. Migrate to the REST API now to avoid disruption.', '{}', 'pending', 'woocommerce.com', '2026-01-13 23:16:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(140, 'existing_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2026-01-23 05:47:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(141, 'prospects_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.', '{}', 'pending', 'woocommerce.com', '2026-01-23 05:47:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(142, 'reddit_q1_2026', 'marketing', 'en_US', 'Start advertising on Reddit with a $1,000 bonus', 'Make the most of our new Reddit integration with $1,000 in Reddit Ads! For a limited time, new advertisers who spend $1,000 in Reddit Ads Manager over 30 days will get $1,000 in ad credit. Your bonus credit unlocks automatically when you hit $1,000 in spend. Use your credit within 30 days.', '{}', 'pending', 'woocommerce.com', '2026-02-05 12:33:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(143, 'wc-admin-scheduled-updates-promotion', 'info', 'en_US', 'Analytics ahora admite las actualizaciones programadas', 'Esto mejora el rendimiento de tu tienda. Activa esta función en Analytics &gt; Ajustes.', '{}', 'unactioned', 'woocommerce-admin', '2026-02-07 05:46:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(144, 'Googleupdate_q1_2026', 'marketing', 'en_US', 'Make every ad dollar count', 'Google for WooCommerce now includes Budget Recommendations. Promote your products across Google — from Search to YouTube and beyond — and get personalized suggestions on where to optimize campaign budgets to reach more shoppers.', '{}', 'pending', 'woocommerce.com', '2026-02-10 22:28:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(145, 'Mailchimp-API-maintenance-feb-2026', 'update', 'en_US', 'Mailchimp Maintenance Feb 28', 'Mailchimp will be carrying out planned API maintenance on February 28 from 11am – 4pm EST. During that time, you may see brief sync interruptions in Mailchimp for WooCommerce. Most data will catch up automatically. See the <a href=\"https://developer.woocommerce.com/2026/02/27/mailchimp-api-maintenance-february-28/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-02-27 05:52:51', NULL, 0, 'plain', '', 0, 0, 'info'),
(146, 'RIN-WC-Security-Update-admin-update-March-2026', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-03-03 05:47:30', NULL, 0, 'plain', '', 0, 0, 'info'),
(147, 'USPS_Scan_Form_Mar2026', 'marketing', 'en_US', 'New: Save time shipping with USPS SCAN Form', 'USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.', '{}', 'pending', 'woocommerce.com', '2026-03-12 07:04:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(148, 'wc-admin-launch-checklist', 'info', 'en_US', '¿Estás preparado para lanzar tu tienda?', 'Para asegurarnos de que nunca tengas esa sensación de «¿Qué se me olvidó?» hemos preparado la lista de comprobación esencial de despegue.', '{}', 'unactioned', 'woocommerce-admin', '2026-06-16 10:49:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(149, 'googleforwoocommerce_q2_2026', 'marketing', 'en_US', 'Limited-time offer: Get 2x your ad spend back in Google Ads', 'New to Google Ads and based in the US? Launch your first Google Ads campaign before June 30 to receive double your ad spend back as Google Ads credit.  \r\n\r\nUse new GenAI tools, YouTube Shopping, and Performance Max campaigns to sell more with WooCommerce and Google — get started today.', '{}', 'pending', 'woocommerce.com', '2026-06-16 10:49:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(150, 'woo-dotcom-course-2026-06-09', 'marketing', 'en_US', 'Learn how to build your store with WooCommerce', 'In this free course, we\'ll help you set up and run your online store with clear, practical guidance.', '{}', 'pending', 'woocommerce.com', '2026-06-16 10:49:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(151, 'APFS-consolidation-jun-26', 'marketing', 'en_US', 'New features in WooCommerce Subscriptions', 'All Products for WooCommerce Subscriptions is now included in WooCommerce Subscriptions — no extra extension required. Create multiple plans for a single product and turn one-time purchases into recurring revenue. Update Subscriptions to version 9.0 to get started.', '{}', 'pending', 'woocommerce.com', '2026-06-25 04:13:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(152, 'paypal_q3_2026', 'marketing', 'en_US', 'Important update to your Braintree integration', 'PayPal Enterprise Payments (formerly Braintree) is now officially owned by Woo. This change brings UI improvements, a long-term roadmap, and active updates from the Woo team, with guaranteed compatibility so your payments never miss a beat.', '{}', 'pending', 'woocommerce.com', '2026-07-09 04:40:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(153, 'stripe-woo-gateway-update-july2026', 'update', 'en_US', 'An important update is required for Stripe for WooCommerce', '<strong>A critical update is required for Stripe for WooCommerce</strong> to address an issue that could lead to fraudulent payment totals. Please update your extension to the latest version immediately.', '{}', 'pending', 'woocommerce.com', '2026-07-15 04:13:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(154, 'usps-hazmat-Wcs-jul', 'marketing', 'en_US', 'USPS HAZMAT enforcement starts July 12', 'If you ship hazardous materials — lithium batteries, aerosols, perfume, paint — USPS adds noncompliance fees starting July 12. WooCommerce Shipping labels stay the same. Declare HAZMAT accurately, remove old HAZMAT marks from reused boxes, and place labels on the address side.', '{}', 'pending', 'woocommerce.com', '2026-07-16 04:16:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(155, '3pdmigration_paytrace_fortis', 'marketing', 'en_US', 'Important update about your Paytrace Gateway', 'Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. When you\'re ready to migrate, we recommend Fortis Payments — their team offers step-by-step migration guidance to help', '{}', 'pending', 'woocommerce.com', '2026-07-16 04:16:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(156, '3pdmigration_paytrace_visa', 'marketing', 'en_US', 'Important update about your Paytrace Gateway', 'Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. As a replacement, we recommend Visa Acceptance Solutions — accept popular payment methods in 97% of territories.', '{}', 'pending', 'woocommerce.com', '2026-07-16 04:16:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(157, 'googleforwoocommerce_q2_2026_row_incentive', 'marketing', 'en_US', 'Choose one of three Google Ads signup offers', 'New to Google Ads? Launch your first campaign and get a budget boost with one of three signup offers. Choose the offer that fits your monthly budget and start reaching more customers in more places. Offer for new advertisers only. Terms apply.', '{}', 'pending', 'woocommerce.com', '2026-07-23 04:18:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(158, 'mollie_incentive_h2_2026_PL', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Boost conversions with BLIK and Przelewy24, alongside Europe’s most popular options, with Mollie’s smooth and reliable checkout experience. Sign up today and process up to PLN 50 000 with 0% fees until December 31. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-07-23 04:18:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(159, 'klaviyo_q3_2026', 'marketing', 'en_US', 'Attn Woo: Klaviyo Customer Hub is here', 'Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.', '{}', 'pending', 'woocommerce.com', '2026-07-31 04:06:04', NULL, 0, 'plain', '', 0, 0, 'info'),
(160, 'woo-subscriptions-update-august2026', 'update', 'en_US', 'Please update WooCommerce Subscriptions now', '<strong>The latest version of WooCommerce Subscriptions includes important security updates.</strong> Please update immediately to ensure your store is protected.', '{}', 'pending', 'woocommerce.com', '2026-08-06 04:06:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(161, 'woocommerce-stripe-update-aug2026', 'update', 'en_US', 'An important update is required for Stripe for WooCommerce', '<strong>There is a critical security update available for Stripe for WooCommerce.</strong> Please update to the latest version immediately.', '{}', 'pending', 'woocommerce.com', '2026-08-07 05:00:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(162, 'fedex-ga-launch-wcs-aug26', 'marketing', 'en_US', 'WooCommerce Shipping now supports FedEx services', 'You can now give customers the speed and convenience of FedEx right from your store dashboard — with no minimum volume requirements. Offer popular domestic and international options, access discounted rates, and simplify your workflow when you ship FedEx on WooCommerce Shipping.', '{}', 'pending', 'woocommerce.com', '2026-08-07 05:00:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(163, 'fedex-ga-wcst-aug26', 'marketing', 'en_US', 'WooCommerce Shipping now supports FedEx services', 'You can now give customers the speed and convenience of FedEx right from your store dashboard — with no minimum volume requirements. Offer popular domestic and international options, access discounted rates, and simplify your workflow when you ship FedEx on WooCommerce Shipping.', '{}', 'pending', 'woocommerce.com', '2026-08-07 05:00:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(164, 'wc-admin-order-withdrawal-feature', 'info', 'en_US', 'Enable order withdrawal for EU regulatory requirements', 'Stores selling to EU countries may need to offer customers a way to withdraw from qualifying orders. Review how to enable the order withdrawal feature in the Advanced settings.', '{}', 'unactioned', 'woocommerce-admin', '2026-09-05 04:14:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(165, 'mollie_incentive_h2_2026_sweden', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Sell more with Swish, Klarna, and Europe’s other most popular options, using Mollie’s smooth and reliable checkout experience. Sign up today and process up to SEK 50,000 with 0% fees until December 31. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-09-11 04:12:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(166, 'google-for-woocommerce-mapi-update', 'update', 'en_US', 'Action Required by October 12, 2026: Your products will stop showing on Google', 'You need to update Google for WooCommerce to the latest version (3.9.4) to continue syncing your products to Google Merchant Center without issues. The Google for WooCommerce version you have installed uses the legacy Content API which has been deprecated and replaced by the advanced <a href=\"https://support.google.com/merchants/answer/16494522?hl=en\">Google Merchant API</a>.', '{}', 'pending', 'woocommerce.com', '2026-09-24 12:13:51', NULL, 0, 'plain', '', 0, 0, 'info');
